/*!40000 ALTER TABLE `services` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(100) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `email` varchar(125) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `phone_num` varchar(20) COLLATE utf8mb4_hungarian_ci DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_hungarian_ci NOT NULL,
  `registered_in` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
